<script setup lang="ts">
import {onMounted,onBeforeUnmount,ref,reactive} from 'vue'
import GrowthRuleManager from './GrowthRuleManager.vue'
import {foregroundRefresh} from './foreground'
import {t} from '../localization/language'
type Client={get<T>(url:string):Promise<T>;post<T>(url:string,data:unknown):Promise<T>}
const props=defineProps<{client:Client;provider?:boolean}>()
type Policy={itemType:string;itemId:string;title:string;ownerType:string;ownerId:string;enabled:boolean;consent:boolean;costCents:number;minimumContributionCents:number;subsidyCapCents:number;revision:number}
type Budget={kind:string;totalCents:number;heldCents:number;spentCents:number;revision:number}
type Proposal={id:number;kind:string;payload:string;reason:string;status:string;createdBy:string;approvedBy:string}
type Dashboard={settings:{enabled:boolean;discountsEnabled:boolean;revision:number};budgets:Budget[];policies:Policy[];proposals:Proposal[]}
type Bill={orderNo:string;orderType:string;status:string;contractGrossCents:number;customerPaidCents:number;platformSubsidyCents:number}
type Content={id:number;title:string;kind:string;body:string;mediaUrl:string;durationSeconds:number;enabled:boolean;revision:number}
type Activity={id:number;title:string;description:string;startsAt:number;endsAt:number;enabled:boolean}
type Support={id:number;userId:string;body:string;level:number;urgency:number;reply:string;status:string}
const root='/payments/growth/',dashboard=ref<Dashboard>(),policies=ref<Policy[]>([]),bills=ref<Bill[]>([]),contents=ref<Content[]>([]),activities=ref<Activity[]>([]),support=ref<Support[]>([]),busy=ref(false),error=ref(''),notice=ref(''),tab=ref('rules')
const policy=reactive<Policy>({itemType:'shop_sku',itemId:'',title:'',ownerType:'',ownerId:'',enabled:false,consent:false,costCents:0,minimumContributionCents:0,subsidyCapCents:0,revision:0})
const content=reactive<Content>({id:0,title:'',kind:'article',body:'',mediaUrl:'',durationSeconds:0,enabled:false,revision:0})
const activity=reactive<Activity>({id:0,title:'',description:'',startsAt:0,endsAt:0,enabled:false})
const starts=ref(''),ends=ref(''),reason=ref(''),adjust=reactive({userId:'',sourceEventId:0,amount:0}),verify=reactive({id:0,userId:'',evidence:''}),budgetTotal=ref(0),budgetKind=ref('level'),audit=ref<unknown[]>([])
type AccountAudit={exists:boolean;userId:string;total:number;level:{code:number;name:string};events:{id:number;kind:string;referenceNo:string;state:string;amount:number;applied:number;createdAt:number}[];hasMore:boolean}
const accountUser=ref(''),accountPage=ref(1),accountAudit=ref<AccountAudit>()
const readAccount=async(page=1)=>{busy.value=true;error.value='';accountAudit.value=undefined;try{accountAudit.value=await props.client.get<AccountAudit>(root+'admin/account?userId='+encodeURIComponent(accountUser.value.trim())+'&page='+page);accountPage.value=page}catch(e){error.value=e instanceof Error?e.message:t('加载失败')}finally{busy.value=false}}
const date=(n:number)=>n?new Date(n*1000).toLocaleString():t('未设置')
const money=(n:number)=>(n/100).toFixed(2)
let live=true,stop:undefined|(()=>void);const settingsDraft=reactive({enabled:false,discountsEnabled:false,revision:0});let settingsBaseline='';
const supportBaseline=new Map<number,{reply:string;urgency:number}>();
function mergeSupport(rows:Support[]){return rows.map(row=>{const previous=support.value.find(s=>s.id===row.id),base=supportBaseline.get(row.id);supportBaseline.set(row.id,{reply:row.reply,urgency:row.urgency});return previous&&base&&(previous.reply!==base.reply||previous.urgency!==base.urgency)?{...row,reply:previous.reply,urgency:previous.urgency}:row})}
const load=async(silent=false)=>{if(!silent){busy.value=true;error.value='';}try{if(props.provider){[policies.value,bills.value]=await Promise.all([props.client.get<Policy[]>(root+'provider/policies'),props.client.get<Bill[]>(root+'provider/bills')])}else{const next=await props.client.get<Dashboard>(root+'admin/dashboard');if(!live)return;if(!settingsBaseline||JSON.stringify(settingsDraft)===settingsBaseline){Object.assign(settingsDraft,next.settings)}settingsBaseline=JSON.stringify(next.settings);dashboard.value=next;policies.value=next.policies;const results=await Promise.all([props.client.get<Content[]>(root+'admin/contents'),props.client.get<Activity[]>(root+'admin/activities'),props.client.get<Support[]>(root+'admin/support'),props.client.get<unknown[]>(root+'admin/audit')]);if(live){contents.value=results[0];activities.value=results[1];support.value=mergeSupport(results[2]);audit.value=results[3]}}}catch(e){error.value=e instanceof Error?e.message:t('加载失败')}finally{busy.value=false}}
const mutate=async(path:string,payload:unknown)=>{busy.value=true;error.value='';notice.value='';try{await props.client.post(root+path,payload);await load();notice.value=t('已保存')}catch(e){error.value=e instanceof Error?e.message:t('操作失败')}finally{busy.value=false}}
const propose=(kind:string,payload:unknown)=>{if(reason.value.trim().length<5){error.value=t('请填写至少五个字的变更理由');return}void mutate('admin/proposal',{kind,payload,reason:reason.value})}
const labels:Record<string,string>={rules:'定时规则',rule_cancel:'取消定时规则',settings:'规则开关',budget:'补贴预算',policy:'参与项目',adjustment:'成长纠正',draft:'待复核',approved:'已通过',rejected:'已驳回',shop_sku:'商城规格',material_sku:'材料规格',material:'材料',temple_service:'寺院服务',master_service:'大师服务',consultation:'即时咨询',ai_report:'现金报告'}
onMounted(()=>{void load();stop=foregroundRefresh(async()=>{await load(true)})});onBeforeUnmount(()=>{live=false;stop?.()})
</script>
<template><div class="growth-ops"><header><div><h1>{{t(provider?'成长优惠参与':'成长体系管理')}}</h1><p>{{t(provider?'平台补贴不改变已确认的服务结算规则。个人成长账户与工作身份分开。':'五级规则统一生效。金额、白名单和人工补偿均需另一位管理员复核。')}}</p></div><button :disabled="busy" @click="load()">{{t('刷新')}}</button></header>
<p v-if="error" role="alert">{{t(error)}}</p><p v-if="notice" role="status">{{notice}}</p><p v-if="busy" role="status">{{t('正在处理…')}}</p>
<template v-if="provider"><GrowthRuleManager :client="client" provider/><section><h2>{{t('参与项目')}}</h2><p>{{t('只有启用且获得同意的项目参与优惠。已支付订单沿用确认时的价格。')}}</p><p v-if="!policies.length&&!busy">{{t('暂无待确认的项目')}}</p><article v-for="p in policies" :key="p.itemType+p.itemId"><h3>{{t(p.title)}} · {{p.itemId}}</h3><p>{{t(labels[p.itemType]||p.itemType)}} · {{t(p.enabled?'平台已启用':'平台未启用')}} · {{t(p.consent?'已同意参与':'尚未同意')}}</p><button :disabled="busy" @click="mutate('provider/consent',{itemType:p.itemType,itemId:p.itemId,revision:p.revision,consent:!p.consent})">{{t(p.consent?'停止后续参与':'同意参与')}}</button></article></section><section><h2>{{t('优惠订单账单')}}</h2><p v-if="!bills.length&&!busy">{{t('暂无优惠订单')}}</p><article v-for="b in bills" :key="b.orderNo"><strong>{{b.orderNo}}</strong><p>{{t('合同金额')}} ¥{{money(b.contractGrossCents)}} · {{t('用户实付')}} ¥{{money(b.customerPaidCents)}} · {{t('平台补贴')}} ¥{{money(b.platformSubsidyCents)}}</p><small>{{t(b.status==='refunded'?'已退款':'已支付')}}</small></article></section></template>
<template v-else-if="dashboard"><nav aria-label="成长管理分类"><button v-for="(label,id) in {rules:'规则与预算',policies:'参与项目',tasks:'学习与活动',support:'客服分流',account:'客户账本',audit:'变更与审计'}" :key="id" :aria-current="tab===id?'page':undefined" @click="tab=id">{{t(label)}}</button></nav>
<section v-if="['rules','policies'].includes(tab)"><label>{{t('变更理由（提交后由另一位管理员复核）')}}<textarea v-model="reason" minlength="5" maxlength="500"/></label></section>
<template v-if="tab==='rules'"><GrowthRuleManager :client="client"/><section><h2>{{t('成长规则')}}</h2><label class="check"><input v-model="settingsDraft.enabled" type="checkbox"/>{{t('开放成长服务')}}</label><label class="check"><input v-model="settingsDraft.discountsEnabled" type="checkbox"/>{{t('启用等级折扣')}}</label><button :disabled="busy" @click="propose('settings',settingsDraft)">{{t('提交开关变更')}}</button></section>
<section><h2>{{t('补贴预算')}}</h2><article v-for="b in dashboard.budgets" :key="b.kind"><strong>{{t(b.kind==='level'?'等级优惠预算':'升级礼券预算')}}</strong><p>{{t('总额')}} ¥{{money(b.totalCents)}} · {{t('占用')}} ¥{{money(b.heldCents)}} · {{t('已用')}} ¥{{money(b.spentCents)}}</p></article><form @submit.prevent="propose('budget',{kind:budgetKind,totalCents:budgetTotal,revision:dashboard.budgets.find(b=>b.kind===budgetKind)?.revision})"><label>{{t('预算类型')}}<select v-model="budgetKind"><option value="level">{{t('等级优惠')}}</option><option value="coupon">{{t('升级礼券')}}</option></select></label><label>{{t('预算总额（分）')}}<input v-model.number="budgetTotal" type="number" min="0" max="100000000" step="1" required/></label><button :disabled="busy">{{t('提交预算变更')}}</button></form><p>{{t('预算默认为零，金额不能低于已用和占用之和。')}}</p></section>
<section><h2>{{t('成长纠正')}}</h2><form @submit.prevent="propose('adjustment',adjust)"><label>{{t('用户 ID')}}<input v-model="adjust.userId" required/></label><label>{{t('撤销来源事件 ID（补偿时填 0）')}}<input v-model.number="adjust.sourceEventId" type="number" min="0" step="1" required/></label><label>{{t('补偿成长值（撤销时填 0，每次最多 200）')}}<input v-model.number="adjust.amount" type="number" min="0" max="200" step="1" required/></label><button :disabled="busy">{{t('提交纠正申请')}}</button></form></section></template>
<template v-if="tab==='policies'"><section><h2>{{t('优惠参与项目')}}</h2><p>{{t('项目默认关闭。需明确成本、最低贡献和单件补贴上限；专业服务还需服务方同意。')}}</p><article v-for="p in policies" :key="p.itemType+p.itemId"><strong>{{t(p.title)}} · {{p.itemId}}</strong><p>{{t(p.enabled?'已启用':'未启用')}} · {{t(p.consent?'已获同意':'等待服务方同意')}} · {{t('单件补贴上限')}} ¥{{money(p.subsidyCapCents)}}</p><button @click="Object.assign(policy,p)">{{t('编辑')}}</button></article><form @submit.prevent="propose('policy',policy)"><label>{{t('项目类型')}}<select v-model="policy.itemType" :disabled="policy.revision>0"><option v-for="id in ['shop_sku','material_sku','material','temple_service','master_service','consultation','ai_report']" :key="id" :value="id">{{t(labels[id])}}</option></select></label><label>{{t('项目编号')}}<input v-model="policy.itemId" :disabled="policy.revision>0" required/><small>{{t('规格填写 ID；服务填写机构或大师编码:服务编码；咨询填写大师编码；报告填写产品编码。')}}</small></label><label v-for="(name,key) in {costCents:'单件成本（分）',minimumContributionCents:'单件最低贡献（分）',subsidyCapCents:'单件补贴上限（分）'}" :key="key">{{t(name)}}<input v-model.number="policy[key]" type="number" min="0" max="100000000" step="1" required/></label><label class="check"><input v-model="policy.enabled" type="checkbox"/>{{t('启用项目')}}</label><div><button :disabled="busy">{{t('提交项目变更')}}</button><button type="button" @click="Object.assign(policy,{itemType:'shop_sku',itemId:'',revision:0,enabled:false,costCents:0,minimumContributionCents:0,subsidyCapCents:0})">{{t('新增项目')}}</button></div></form></section></template>
<template v-if="tab==='tasks'"><section><h2>{{t('学习内容')}}</h2><article v-for="c in contents" :key="c.id"><strong>{{t(c.title)}}</strong> · {{t(c.enabled?'已开放':'未开放')}} <button @click="Object.assign(content,c)">{{t('编辑')}}</button></article><form @submit.prevent="mutate('admin/contents',{content})"><label>{{t('标题')}}<input v-model="content.title" required maxlength="120"/></label><label>{{t('内容类型')}}<select v-model="content.kind"><option value="article">{{t('文章')}}</option><option value="media">{{t('音视频')}}</option></select></label><label>{{t('正文')}}<textarea v-model="content.body" :minlength="content.kind==='article'?100:0" maxlength="60000" :required="content.kind==='article'"/></label><template v-if="content.kind==='media'"><label>{{t('媒体地址（HTTPS）')}}<input v-model="content.mediaUrl" type="url" required/></label><label>{{t('时长（秒）')}}<input v-model.number="content.durationSeconds" type="number" min="60" max="7200" required/></label></template><label class="check"><input v-model="content.enabled" type="checkbox"/>{{t('开放学习')}}</label><div><button :disabled="busy">{{t('保存内容')}}</button><button type="button" @click="Object.assign(content,{id:0,title:'',body:'',revision:0,enabled:false})">{{t('新增内容')}}</button></div></form></section>
<section><h2>{{t('官方活动')}}</h2><article v-for="a in activities" :key="a.id"><strong>#{{a.id}} {{t(a.title)}}</strong><p>{{date(a.startsAt)}} — {{date(a.endsAt)}}</p><button @click="Object.assign(activity,a);starts=new Date(a.startsAt*1000-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16);ends=new Date(a.endsAt*1000-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16)">{{t('编辑')}}</button></article><form @submit.prevent="mutate('admin/activities',{activity:{...activity,startsAt:Math.floor(new Date(starts).getTime()/1000),endsAt:Math.floor(new Date(ends).getTime()/1000)}})"><label>{{t('活动标题')}}<input v-model="activity.title" required maxlength="120"/></label><label>{{t('活动说明')}}<textarea v-model="activity.description" required maxlength="2000"/></label><label>{{t('开始时间')}}<input v-model="starts" type="datetime-local" required/></label><label>{{t('结束时间')}}<input v-model="ends" type="datetime-local" required/></label><label class="check"><input v-model="activity.enabled" type="checkbox"/>{{t('开放登记')}}</label><div><button :disabled="busy">{{t('保存活动')}}</button><button type="button" @click="Object.assign(activity,{id:0,title:'',description:'',enabled:false});starts='';ends=''">{{t('新增活动')}}</button></div></form></section>
<section><h2>{{t('参与核验')}}</h2><form @submit.prevent="mutate('admin/attendance',verify)"><label>{{t('活动 ID')}}<input v-model.number="verify.id" type="number" min="1" required/></label><label>{{t('用户 ID')}}<input v-model="verify.userId" required/></label><label>{{t('核验依据')}}<textarea v-model="verify.evidence" required maxlength="255"/></label><button :disabled="busy">{{t('确认实际参与')}}</button></form><p>{{t('仅可核验已登记且已开始的活动；重复核验不重复奖励。')}}</p></section></template>
<section v-if="tab==='support'"><h2>{{t('客服分流')}}</h2><p>{{t('先按紧急程度，再在同紧急程度下优先处理致远及以上用户。')}}</p><p v-if="!support.length">{{t('暂无客服诉求')}}</p><article v-for="s in support" :key="s.id"><strong>{{t('用户')}} {{s.userId}} · L{{s.level}} · {{t(s.status==='replied'?'已回复':'待处理')}}</strong><p class="prose">{{s.body}}</p><form @submit.prevent="mutate('admin/support',{id:s.id,reply:s.reply,urgency:s.urgency})"><label>{{t('紧急程度')}}<select v-model.number="s.urgency"><option :value="0">{{t('一般')}}</option><option :value="1">{{t('优先')}}</option><option :value="2">{{t('紧急')}}</option></select></label><label>{{t('回复用户')}}<textarea v-model="s.reply" required maxlength="2000"/></label><button :disabled="busy">{{t('保存回复')}}</button></form></article></section>
<section v-if="tab==='account'"><h2>{{t('客户成长账本')}}</h2><p>{{t('仅展示记账依据，不展示私人行动记录正文。')}}</p><form @submit.prevent="readAccount(1)"><label>{{t('用户 ID')}}<input v-model="accountUser" required maxlength="64"/></label><button :disabled="busy">{{t('查询')}}</button></form><template v-if="accountAudit"><p v-if="!accountAudit.exists">{{t('尚无成长账本')}}</p><template v-else><h3>{{accountAudit.userId}} · L{{accountAudit.level.code}} {{t(accountAudit.level.name)}} · {{accountAudit.total}} {{t('成长值')}}</h3><article v-for="e in accountAudit.events" :key="e.id"><strong>{{t('来源事件')}} #{{e.id}} · {{e.kind}}</strong><p>{{e.referenceNo}} · {{date(e.createdAt)}} · {{e.state}}</p><p>{{t('有效成长')}} {{e.amount}} · {{t('已记账')}} {{e.applied}}</p><button @click="adjust.userId=accountAudit.userId;adjust.sourceEventId=e.id;adjust.amount=0;tab='rules'">{{t('申请纠正此事件')}}</button></article><button :disabled="busy||accountPage===1" @click="readAccount(accountPage-1)">{{t('上一页')}}</button><button :disabled="busy||!accountAudit.hasMore" @click="readAccount(accountPage+1)">{{t('下一页')}}</button></template></template></section>
<template v-if="tab==='audit'"><section><h2>{{t('待复核与历史变更')}}</h2><article v-for="p in dashboard.proposals" :key="p.id"><h3>#{{p.id}} {{t(labels[p.kind]||p.kind)}} · {{t(labels[p.status]||p.status)}}</h3><p>{{t('理由')}}：{{p.reason}}</p><p>{{t('申请人')}} {{p.createdBy}} · {{t('复核人')}} {{p.approvedBy||'—'}}</p><pre>{{JSON.stringify(JSON.parse(p.payload),null,2)}}</pre><div v-if="p.status==='draft'"><button :disabled="busy" @click="mutate('admin/approve',{id:p.id,approve:true})">{{t('通过复核')}}</button><button :disabled="busy" @click="mutate('admin/approve',{id:p.id,approve:false})">{{t('驳回')}}</button></div></article></section><section><h2>{{t('审计记录')}}</h2><details v-for="(row,i) in audit" :key="i"><summary>{{t('记录')}} {{i+1}}</summary><pre>{{JSON.stringify(row,null,2)}}</pre></details></section></template>
</template></div></template>
<style scoped>
.growth-ops{max-width:1120px;margin:auto;display:grid;gap:20px;color:var(--el-text-color-primary)}header{display:flex;justify-content:space-between;gap:16px;align-items:flex-start}h1{font-size:24px;margin:0}h2{font-size:19px;margin:0 0 14px}h3{font-size:16px}p,small{line-height:1.8;color:var(--el-text-color-secondary)}section{background:var(--el-bg-color);border:1px solid var(--el-border-color);border-radius:14px;padding:22px;min-width:0}nav{display:flex;gap:10px;flex-wrap:wrap}button{min-height:40px;padding:8px 16px;border:1px solid var(--el-border-color);border-radius:8px;background:var(--el-bg-color);color:var(--el-text-color-primary);cursor:pointer;font:inherit;margin:4px 8px 4px 0}button[aria-current]{border-color:var(--el-color-primary);color:var(--el-color-primary)}button:disabled{opacity:.5;cursor:default}article{padding:18px 0;border-bottom:1px solid var(--el-border-color-lighter)}form{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));align-items:end;gap:16px;margin-top:18px}label{display:grid;gap:8px;font-size:14px}label.check{display:flex;align-items:center;min-height:40px}input:not([type=checkbox]),textarea,select{box-sizing:border-box;width:100%;font:inherit;min-height:40px;background:var(--el-fill-color-blank);color:var(--el-text-color-primary);border:1px solid var(--el-border-color);border-radius:8px;padding:9px 12px}textarea{min-height:90px}input[type=checkbox]{width:18px;height:18px}pre,.prose{white-space:pre-wrap;overflow-wrap:anywhere}pre{padding:14px;background:var(--el-fill-color-light);font-size:13px}details{margin-top:12px}summary{cursor:pointer}button:focus-visible,input:focus-visible,textarea:focus-visible{outline:2px solid var(--el-color-primary);outline-offset:3px}
</style>
